  sample_rate: 16000 | 48000;
  frame_length_ms: 20 | 30; // 30ms provides better pitch stability
  min_silence_duration_ms: 250; 
  speech_pad_ms: 150;
  threshold: number; // Sensitivity: 0.0 (aggressive) to 1.0 (conservative)
}

