  sample_rate: 16000,
  frame_length_ms: 30,
  min_silence_duration_ms: 250,
  speech_pad_ms: 150,
  threshold: 0.55 // Balanced for high-fidelity speech capture
};

export const adaptiveVadTrigger = (energy: number, threshold: number): boolean => {
  // Logic: Signal energy compared against dynamic floor
  return energy > threshold;
};
